div.script:
                    (function(){
                        function fetchProducts(){
                            var configId = document.getElementById('store_select').value || '';
                            var grid = document.getElementById('product_grid');

                            // Show loading
                            grid.innerHTML = '

正在載入美味餐點...';

                            odoo.jsonRpc('/wuchang/delivery/products', 'call', {config_id: configId}).then(function(res){
                                grid.innerHTML = '';
                                if (!res.items || res.items.length === 0) {
                                    grid.innerHTML = '

此分類目前沒有商品';
                                    return;
                                }

                                (res.items||[]).forEach(function(it){
                                    var card = document.createElement('div');
                                    card.className = 'bg-white rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow overflow-hidden group flex flex-col h-full';

                                    // Image Section
                                    var imgHtml = '
';
                                    if(it.image) {
                                        imgHtml += '';
                                    } else {
                                        imgHtml += '
';
                                    }
                                    // Badge
                                    imgHtml += '
25-35 分';
                                    imgHtml += '';

                                    // Content Section
                                    var contentHtml = '
';
                                    contentHtml += '
';
                                    contentHtml += '  
'+(it.name||'未命名商品')+'';
                                    contentHtml += '  公益';
                                    contentHtml += '';

                                    contentHtml += '
'+(it.description || '暫無描述')+'';

                                    contentHtml += '
';
                                    contentHtml += '  
';
                                    contentHtml += '    憑券兌換';
                                    contentHtml += '    $'+(it.price||0)+'';
                                    contentHtml += '  ';
                                    contentHtml += '  ';
                                    contentHtml += '';
                                    contentHtml += '';

                                    card.innerHTML = imgHtml + contentHtml;

                                    // Add click event (optional)
                                    card.style.cursor = 'pointer';
                                    card.onclick = function() {
                                        // TODO: Add to cart logic
                                        alert('已將 ' + (it.name||'') + ' 加入購物車');
                                    };

                                    grid.appendChild(card);
                                });
                            });
                        }

                        document.addEventListener('DOMContentLoaded', function(){
                            var sel = document.getElementById('store_select');
                            if(sel) {
                                sel.addEventListener('change', fetchProducts);
                                fetchProducts();
                            }
                        });
                    })();
